1	/* eslint-disable @typescript-eslint/explicit-function-return-type -- Transparent observers preserve the real runtime signatures. */
2	/* eslint-disable @typescript-eslint/consistent-type-imports -- importOriginal describes the observed module. */
3	import "fake-indexeddb/auto";
4	
5	import { ed25519 } from "@noble/curves/ed25519.js";
6	import { encodeCanonical } from "@ts-drp/canonical";
7	import type { V3AdmittedVertexSink, V3PlaneHandle } from "@ts-drp/node/v3-live";
8	import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
9	
10	import { fakeNetwork } from "./fixtures/phase-4b-v3/live-snapshot.js";
11	import { createV3ChatApplication } from "../examples/v3-chat/src/index.js";
12	import {
13		createV3RoomCreatorInviteMaterial,
14		createV3RoomSession,
15		type CreateV3RoomSessionInput,
16		type V3RoomHeadState,
17		type V3RoomSession,
18	} from "../examples/v3-room/src/index.js";
19	import { createRecoverableFinalitySigner } from "../packages/keychain/src/finality.js";
20	
21	type Delivery = Parameters<V3AdmittedVertexSink>[0];
22	const observed = vi.hoisted(() => ({
23		phase: "prepare" as "prepare" | "reopen",
24		fault: "none" as "none" | "sink" | "commit" | "second-commit",
25		deliveries: [] as Delivery[],
26		events: [] as string[],
27		handles: [] as V3PlaneHandle[],
28		transportCloses: 0,
29	}));
30	
31	// Resolve the existing adoption exports to the same source-module identity as
32	// vite.config.mts's v3-live/creator-close aliases. These are real implementations,
33	// not manufactured capabilities, transition records or future exports.
34	vi.mock("../packages/node/dist/src/creator-adoption.js", () => import("../packages/node/src/creator-adoption.js"));
35	vi.mock(
36		"../packages/node/dist/src/creator-adoption-stage.js",
37		() => import("../packages/node/src/creator-adoption-stage.js")
38	);
39	vi.mock(
40		"../packages/node/dist/src/creator-adoption-recover.js",
41		() => import("../packages/node/src/creator-adoption-recover.js")
42	);
43	vi.mock("../packages/node/dist/src/creator-adoption-activate.js", async () => {
44		const actual = await import("../packages/node/src/creator-adoption-activate.js");
45		const observe = async (owner: typeof actual.reopenCreatorSuccessorAdoption, value: unknown) => {
46			const input = value as Record<string, unknown> & { onAdmittedVertex: V3AdmittedVertexSink };
47			const result = await owner({
48				...input,
49				onAdmittedVertex: async (delivery: Delivery) => {
50					observed.deliveries.push(structuredClone(delivery));
51					if (observed.phase === "reopen") {
52						observed.events.push(`sink:${delivery.vertex.authorSequence}`);
53						if (observed.fault === "sink") throw new Error("D110C_0C1F5B0U_REPLAY_SINK_FAILED");
54					}
55					return await input.onAdmittedVertex(delivery);
56				},
57			});
58			if (result.ok === true) observed.handles.push(result.handle as V3PlaneHandle);
59			return result;
60		};
61		return {
62			...actual,
63			activateCreatorSuccessorAdoption: (input: unknown) => observe(actual.activateCreatorSuccessorAdoption, input),
64			reopenCreatorSuccessorAdoption: (input: unknown) => observe(actual.reopenCreatorSuccessorAdoption, input),
65		};
66	});
67	
68	vi.mock("@ts-drp/node/v3-live", async (importOriginal) => {
69		const actual = await importOriginal<typeof import("@ts-drp/node/v3-live")>();
70		return {
71			...actual,
72			bindV3BlueprintLivePlane: (...args: Parameters<typeof actual.bindV3BlueprintLivePlane>) => {
73				const result = actual.bindV3BlueprintLivePlane(...args);
74				if (observed.phase === "reopen" && Reflect.get(args[0], "purpose") === "projection-base" && result.ok)
75					observed.events.push("authenticated-projection-base");
76				return result;
77			},
78		};
79	});
80	
81	const sessions: V3RoomSession[] = [];
82	const seed = new Uint8Array(32).fill(73);
83	const publicKey = ed25519.getPublicKey(seed);
84	const author = Buffer.from(publicKey).toString("hex");
85	const originalStorage = Object.getOwnPropertyDescriptor(navigator, "storage");
86	let ordinal = 0;
87	
88	function required<T>(value: T | undefined | null): T {
89		if (value === undefined || value === null) throw new TypeError("D110C_0C1F5B0U_REPLAY_FIXTURE_MISSING");
90		return value;
91	}
92	
93	function request<T>(value: IDBRequest<T>): Promise<T> {
94		return new Promise((resolve, reject) => {
95			value.onsuccess = () => resolve(value.result);
96			value.onerror = () => reject(value.error);
97		});
98	}
99	
100	// Read the declaration actually produced by seal/adoption, exactly as the
101	// retained D.108 successor room fixture does. Never synthesize epoch authority.
102	async function snapshotDeclaration(databaseName: string) {
103		const database = await request(indexedDB.open(`${databaseName}--drp-snapshot-quarantine-v1`));
104		try {
105			const transaction = database.transaction(["chunks", "scopes"], "readonly");
106			const [scopes, chunks] = await Promise.all([
107				request(transaction.objectStore("scopes").getAll()) as Promise<Record<string, unknown>[]>,
108				request(transaction.objectStore("chunks").getAll()) as Promise<Record<string, unknown>[]>,
109			]);
110			// The close snapshots predecessor epoch 0; its verified payload is the
111			// authenticated application base imported by the epoch-1 successor.
112			const verified = scopes.filter((scope) => scope.state === "verified" && scope.epoch === 0);
113			if (verified.length !== 1) throw new TypeError("D110C_0C1F5B0U_REPLAY_SNAPSHOT_AMBIGUOUS");
114			const scope = required(verified[0]);
115			const selected = chunks
116				.filter((row) => ["objectId", "epoch", "anchor", "manifestDigest"].every((key) => row[key] === scope[key]))
117				.sort((left, right) => Number(left.index) - Number(right.index));
118			if (selected.length !== scope.chunkCount) throw new TypeError("D110C_0C1F5B0U_REPLAY_SNAPSHOT_INCOMPLETE");
119			return {
120				chunks: selected.map((row) => ({ byteLength: row.byteLength, digest: row.digest, index: row.index })),
121				exactCanonicalManifestBytes: new Uint8Array(scope.exactCanonicalManifestBytes as Uint8Array),
122				scope: {
123					anchor: scope.anchor,
124					epoch: scope.epoch,
125					manifestDigest: scope.manifestDigest,
126					objectId: scope.objectId,
127				},
128				totalBytes: scope.totalBytes,
129			} as NonNullable<CreateV3RoomSessionInput["successorSnapshotDeclaration"]>;
130		} finally {
131			database.close();
132		}
133	}
134	
135	async function genuineSuccessor() {
136		const identity = ++ordinal;
137		const databaseName = `d110c-f5b0u-successor-replay-${identity}`;
138		const objectId = `creator:${identity.toString(16).padStart(32, "0")}`;
139		const base = createV3ChatApplication("alice");
140		const migration = required(base.migration);
141		const application = {
142			...base,
143			migration: {
144				...migration,
145				canonicalStateBytes: (...args: Parameters<typeof migration.canonicalStateBytes>) => {
146					const bytes = migration.canonicalStateBytes(...args);
147					if (observed.phase === "reopen") observed.events.push("validated-application-state");
148					return bytes;
149				},
150			},
151		};
152		const signers = [{ publicKey: author, signerId: "creator" }];
153		const creatorInvite = await createV3RoomCreatorInviteMaterial({
154			blueprintDigest: required(base.catalog.blueprintDigests[0]),
155			exactCanonicalApplicationStateBytes: encodeCanonical([]),
156			exactCanonicalLatchedAclBytes: encodeCanonical({
157				epoch: 0,
158				kind: "drp-v3-latched-acl",
159				members: [{ author, finalityKey: author, groups: ["admin", "finality", "writer"] }],
160				objectId,
161				permissionless: false,
162				version: 1,
163			}),
164			exactCanonicalParametersCarrierBytes: encodeCanonical({
165				maxDependencies: 16,
166				maxEpochBytes: 8_388_608,
167				maxEpochVertices: 8192,
168				maxPendingBytes: 16_777_216,
169				maxPendingEntries: 4096,
170				maxSnapshotBytes: 268_435_456,
171				snapshotChunkBytes: 131_072,
172			}),
173			exactCanonicalProfileBytes: encodeCanonical({
174				cryptoSuiteId: "ed25519-sha256-v3",
175				profileId: "creator-trusted-v1",
176				quorum: 1,
177				signers,
178			}),
179			exactCanonicalSignerSetBytes: encodeCanonical(signers),
180			objectId,
181			signGenesisAnchorDigest: (digest) => Promise.resolve(ed25519.sign(digest, seed)),
182		});
183		let state: V3RoomHeadState | null = null;
184		const success = () => ({ ok: true as const, state: structuredClone(state) });
185		const roomHeadAuthority: CreateV3RoomSessionInput["roomHeadAuthority"] = {
186			initialization: { kind: "create" },
187			read: () => Promise.resolve(success()),
188			create: async (input) => {
189				await Promise.resolve();
190				if (state === null) state = { pending: null, stable: input.stable };
191				return success();
192			},
193			migrate: () => Promise.resolve({ ok: false, reason: "conflict" }),
194			begin: async (input) => {
195				await Promise.resolve();
196				if (!Buffer.from(encodeCanonical(input.expected)).equals(Buffer.from(encodeCanonical(state))))
197					return { ok: false, reason: "conflict" };
198				const previous = required(state).stable;
199				state = { stable: previous, pending: { previous, next: input.next } };
200				return success();
201			},
202			commit: async (input) => {
203				await Promise.resolve();
204				if (!Buffer.from(encodeCanonical(input.expected)).equals(Buffer.from(encodeCanonical(state))))
205					return { ok: false, reason: "conflict" };
206				state = { pending: null, stable: required(required(state).pending).next };
207				return success();
208			},
209		};
210		const finality = await createRecoverableFinalitySigner({ seed });
211		const accepted: string[] = [];
212		const input: CreateV3RoomSessionInput = {
213			application,
214			author,
215			creatorInvite,
216			databaseName,
217			initialLogicalTime: 3,
218			issuanceDatabaseName: databaseName,
219			objectId,
220			onAcceptedVertex: (vertex) => {
221				if (observed.phase !== "reopen") return;
222				observed.events.push(`commit:${vertex.authorSequence}`);
223				if (observed.fault === "commit") throw new Error("D110C_0C1F5B0U_REPLAY_COMMIT_FAILED");
224				if (observed.fault === "second-commit" && accepted.length === 1) {
225					observed.fault = "none";
226					throw new Error("D110C_0C1F5B0U_REPLAY_SECOND_COMMIT_FAILED");
227				}
228				accepted.push(Buffer.from(vertex.digest).toString("hex"));
229			},
230			onProjection: () => undefined,
231			openTransport: () => ({
232				networkNode: fakeNetwork(databaseName),
233				close: () => {
234					observed.transportCloses += 1;
235				},
236				openEphemeral: () => {
237					throw new Error("not used");
238				},
239				requestRetainedHistory: () => undefined,
240				setIngressHandler: () => undefined,
241				setRetainedPublisher: () => undefined,
242			}),
243			publicKeyBytes: publicKey,
244			roomHeadAuthority,
245			signRegisteredVertexDigest: (digest) => Promise.resolve(ed25519.sign(digest, seed)),
246		};
247		const room = await createV3RoomSession({ ...input, creatorFinalitySigner: finality.signer });
248		sessions.push(room);
249		await room.issue({ action: "message", clientOperationId: "snapshot", text: "snapshot" });
250		const sealed = await room.sealEpoch();
251		if (sealed.ok !== true) throw new TypeError(`D110C_0C1F5B0U_REPLAY_CLOSE_FAILED:${JSON.stringify(sealed)}`);
252		await room.adoptCreatorSuccessor();
253		if (room.authority()?.epoch !== 1) throw new TypeError("D110C_0C1F5B0U_REPLAY_ADOPTION_FAILED");
254		observed.deliveries = [];
255		for (const clientOperationId of ["above-snapshot-1", "above-snapshot-2"])
256			await room.issue({ action: "message", clientOperationId, text: clientOperationId });
257		const expected = structuredClone(observed.deliveries);
258		if (expected.length !== 2) throw new TypeError("D110C_0C1F5B0U_REPLAY_ISSUED_EVIDENCE_INCOMPLETE");
259		const projection = room.projection();
260		const authority = room.authority();
261		const declaration = await snapshotDeclaration(databaseName);
262		await room.close();
263		sessions.splice(sessions.indexOf(room), 1);
264		observed.phase = "reopen";
265		observed.deliveries = [];
266		observed.events = [];
267		observed.transportCloses = 0;
268		const reopen = async () => {
269			const reopened = await createV3RoomSession({
270				...input,
271				roomHeadAuthority: { ...roomHeadAuthority, initialization: { kind: "reopen" } },
272				successorSnapshotDeclaration: declaration,
273			});
274			sessions.push(reopened);
275			return reopened;
276		};
277		return { accepted, authority, expected, projection, reopen };
278	}
279	
280	beforeEach(() => {
281		Object.defineProperty(navigator, "storage", {
282			configurable: true,
283			value: { estimate: () => Promise.resolve({ quota: 1_000_000_000_000, usage: 0 }) },
284		});
285		observed.phase = "prepare";
286		observed.fault = "none";
287		observed.deliveries = [];
288		observed.events = [];
289		observed.handles = [];
290		observed.transportCloses = 0;
291	});
292	
293	afterEach(async () => {
294		observed.fault = "none";
295		await Promise.all(sessions.splice(0).map((session) => session.close().catch(() => undefined)));
296		await Promise.all(observed.handles.map((handle) => Promise.resolve(handle.deactivate())));
297		if (originalStorage === undefined) Reflect.deleteProperty(navigator, "storage");
298		else Object.defineProperty(navigator, "storage", originalStorage);
299	});
300	
301	describe("D.110c-0c1f5b0u genuine successor recovered-delivery RED", () => {
302		it("replays exact above-snapshot evidence once after authority/base validation and before resumed issue", async () => {
303			const fixture = await genuineSuccessor();
304			const reopened = await fixture.reopen();
305			const replay = [...observed.deliveries];
306			const expectedDigests = fixture.expected.map(({ vertex }) => Buffer.from(vertex.digest).toString("hex"));
307			expect
308				.soft(
309					replay.map(({ vertex }) => Buffer.from(vertex.digest).toString("hex")),
310					"REPLAY_EXACT_ORDER"
311				)
312				.toEqual(expectedDigests);
313			expect
314				.soft(
315					replay.map(({ exactReceivedCanonicalPreimageBytes, signature }) => ({
316						exactReceivedCanonicalPreimageBytes,
317						signature,
318					})),
319					"REPLAY_EXACT_BYTES_SIGNATURES"
320				)
321				.toEqual(
322					fixture.expected.map(({ exactReceivedCanonicalPreimageBytes, signature }) => ({
323						exactReceivedCanonicalPreimageBytes,
324						signature,
325					}))
326				);
327			expect.soft(fixture.accepted, "REPLAY_EXACTLY_ONCE_COMMIT").toEqual(expectedDigests);
328			const canonicalStateBytes = required(createV3ChatApplication("alice").migration).canonicalStateBytes;
329			expect
330				.soft(Reflect.apply(canonicalStateBytes, undefined, [reopened.projection()]), "REPLAY_RECOVERS_APPLICATION_STATE")
331				.toEqual(Reflect.apply(canonicalStateBytes, undefined, [fixture.projection]));
332			const reopenedMessages = Reflect.get(reopened.projection(), "accepted") as readonly Record<string, unknown>[];
333			expect
334				.soft(
335					reopenedMessages.filter((message) => message.provenance === "authenticated-snapshot"),
336					"REPLAY_AUTHENTICATED_SNAPSHOT_PROVENANCE"
337				)
338				.toEqual([{ clientOperationId: "snapshot", provenance: "authenticated-snapshot", text: "snapshot" }]);
339			expect.soft(reopened.authority()).toEqual(fixture.authority);
340			const validation = observed.events.indexOf("validated-application-state");
341			expect.soft(observed.events.indexOf("authenticated-projection-base")).toBeGreaterThanOrEqual(0);
342			for (const { vertex } of fixture.expected) {
343				expect
344					.soft(observed.events.indexOf(`sink:${vertex.authorSequence}`), "REPLAY_SINK_PRESENT")
345					.toBeGreaterThanOrEqual(0);
346				expect
347					.soft(observed.events.indexOf(`commit:${vertex.authorSequence}`), "REPLAY_COMMIT_AFTER_VALIDATION")
348					.toBeGreaterThan(validation);
349			}
350			observed.events.push("public-issue");
351			await reopened.issue({ action: "message", clientOperationId: "resumed", text: "resumed" });
352			expect.soft(fixture.accepted.slice(0, 2), "REPLAY_BEFORE_PUBLIC_ISSUE").toEqual(expectedDigests);
353			expect.soft(new Set(fixture.accepted).size, "REPLAY_NO_DUPLICATE_COMMIT").toBe(3);
354			expect
355				.soft(
356					observed.handles.filter((handle) => handle.currentEphemeralAuthority() !== undefined),
357					"REPLAY_ONE_ACTIVE_OWNER"
358				)
359				.toHaveLength(1);
360		});
361	
362		it("preserves external delivery custody when callback two fails after callback one and the same room cold-reopens", async () => {
363			const fixture = await genuineSuccessor();
364			const expectedDigests = fixture.expected.map(({ vertex }) => Buffer.from(vertex.digest).toString("hex"));
365			observed.fault = "second-commit";
366			const outcome = await fixture.reopen().then(
367				() => "unexpected-success",
368				() => "rejected"
369			);
370			expect.soft(outcome, "REPLAY_SECOND_FAILURE_REFUSED").toBe("rejected");
371			expect
372				.soft(
373					observed.events.filter((event) => event.startsWith("commit:")),
374					"REPLAY_SECOND_CALLBACK_REACHED"
375				)
376				.toEqual(fixture.expected.map(({ vertex }) => `commit:${vertex.authorSequence}`));
377			expect.soft(observed.fault, "REPLAY_SECOND_FAULT_CONSUMED_ONCE").toBe("none");
378			expect
379				.soft(
380					observed.handles.filter((handle) => handle.currentEphemeralAuthority() !== undefined),
381					"REPLAY_SECOND_FAILURE_NO_ACTIVE_OWNER"
382				)
383				.toHaveLength(0);
384			expect.soft(observed.transportCloses, "REPLAY_SECOND_FAILURE_TRANSPORT_RELEASED").toBe(1);
385			// This ledger is external observer state: do not reset or deduplicate it across reopen.
386			expect.soft([...fixture.accepted], "REPLAY_SECOND_FAILURE_ATOMIC_EXTERNAL_LEDGER").toEqual([]);
387			observed.fault = "none";
388			const recovered = await fixture.reopen();
389			expect.soft(fixture.accepted, "REPLAY_COLD_REOPEN_IDEMPOTENT_EXTERNAL_LEDGER").toEqual(expectedDigests);
390			const canonicalStateBytes = required(createV3ChatApplication("alice").migration).canonicalStateBytes;
391			expect
392				.soft(
393					Reflect.apply(canonicalStateBytes, undefined, [recovered.projection()]),
394					"REPLAY_RECOVERY_CANONICAL_STATE_ONCE"
395				)
396				.toEqual(Reflect.apply(canonicalStateBytes, undefined, [fixture.projection]));
397			const messages = Reflect.get(recovered.projection(), "accepted") as readonly Record<string, unknown>[];
398			expect
399				.soft(messages.map((message) => message.clientOperationId).sort(), "REPLAY_RECOVERY_EACH_DURABLE_OPERATION_ONCE")
400				.toEqual(["above-snapshot-1", "above-snapshot-2", "snapshot"]);
401			expect.soft(recovered.authority(), "REPLAY_RECOVERY_AUTHORITY_UNCHANGED").toEqual(fixture.authority);
402			expect
403				.soft(
404					observed.handles.filter((handle) => handle.currentEphemeralAuthority() !== undefined),
405					"REPLAY_RECOVERY_ONE_ACTIVE_OWNER"
406				)
407				.toHaveLength(1);
408		});
409	
410		for (const fault of ["sink", "commit"] as const) {
411			it(`fails closed and releases successor custody when recovered ${fault} fails`, async () => {
412				const fixture = await genuineSuccessor();
413				observed.fault = fault;
414				const outcome = await fixture.reopen().then(
415					() => "unexpected-success",
416					() => "rejected"
417				);
418				expect.soft(outcome, "REPLAY_FAILURE_REFUSED").toBe("rejected");
419				expect.soft(observed.deliveries.length, "REPLAY_FAILURE_SEAM_REACHED").toBeGreaterThan(0);
420				expect
421					.soft(
422						observed.handles.filter((handle) => handle.currentEphemeralAuthority() !== undefined),
423						"REPLAY_FAILURE_NO_ACTIVE_OWNER"
424					)
425					.toHaveLength(0);
426				expect.soft(observed.transportCloses, "REPLAY_FAILURE_TRANSPORT_RELEASED").toBe(1);
427				expect.soft(fixture.accepted, "REPLAY_FAILURE_NO_PARTIAL_COMMIT").toEqual([]);
428			});
429		}
430	});
